# (populates ~10 min after the market opens), so a single
# earliest-scan replay would read "no trade" for structural
# reasons. One answer per window shows which interval actually
# has tradeable prices AND which one makes money.
def _lead_bk(scan_rows):
    lm = None
    for r in scan_rows:
        if r.get("lead_min") is not None:
            lm = float(r["lead_min"])
            break
